#### Step 2: Implement Correlation ID Middleware

**.NET Middleware**:
```csharp
// CorrelationIdMiddleware.cs
public class CorrelationIdMiddleware
{
    private const string CorrelationIdHeader = "X-Correlation-ID";
    private readonly RequestDelegate _next;
    private readonly ILogger<CorrelationIdMiddleware> _logger;

    public CorrelationIdMiddleware(RequestDelegate next, ILogger<CorrelationIdMiddleware> logger)
    {
        _next = next;
        _logger = logger;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        // Extract correlation ID from header or generate new one
        string correlationId = context.Request.Headers[CorrelationIdHeader].FirstOrDefault()
            ?? Guid.NewGuid().ToString();

        // Store in AsyncLocal for access throughout request
        CorrelationContext.CorrelationId = correlationId;

        // Add to Serilog log context
        using (LogContext.PushProperty("CorrelationId", correlationId))
        {
            // Add correlation ID to response headers for client reference
            context.Response.Headers.Add(CorrelationIdHeader, correlationId);

            _logger.LogInformation("Request received {Method} {Path}",
                context.Request.Method,
                context.Request.Path);

            await _next(context);

            _logger.LogInformation("Request completed {Method} {Path} {StatusCode}",
                context.Request.Method,
                context.Request.Path,
                context.Response.StatusCode);
        }
    }
}

// CorrelationContext.cs
public static class CorrelationContext
{
    private static readonly AsyncLocal<string> _correlationId = new AsyncLocal<string>();

    public static string CorrelationId
    {
        get => _correlationId.Value;
        set => _correlationId.Value = value;
    }
}

// Program.cs registration
app.UseMiddleware<CorrelationIdMiddleware>();
```

**Java Spring Boot Filter**:
```java
@Component
@Order(1)
public class CorrelationIdFilter implements Filter {

    private static final String CORRELATION_ID_HEADER = "X-Correlation-ID";
    private static final Logger logger = LoggerFactory.getLogger(CorrelationIdFilter.class);

    @Override
    public void doFilter(ServletRequest request, ServletResponse response, FilterChain chain)
            throws IOException, ServletException {

        HttpServletRequest httpRequest = (HttpServletRequest) request;
        HttpServletResponse httpResponse = (HttpServletResponse) response;

        // Extract or generate correlation ID
        String correlationId = httpRequest.getHeader(CORRELATION_ID_HEADER);
        if (correlationId == null || correlationId.isEmpty()) {
            correlationId = UUID.randomUUID().toString();
        }

        // Store in MDC (Mapped Diagnostic Context)
        MDC.put("correlationId", correlationId);

        // Add to response headers
        httpResponse.setHeader(CORRELATION_ID_HEADER, correlationId);

        try {
            logger.info("Request received: {} {}", httpRequest.getMethod(), httpRequest.getRequestURI());
            chain.doFilter(request, response);
            logger.info("Request completed: {} {} {}",
                httpRequest.getMethod(),
                httpRequest.getRequestURI(),
                httpResponse.getStatus());
        } finally {
            // Clean up MDC
            MDC.remove("correlationId");
        }
    }
}
```

**Node.js/Express Middleware**:
```javascript
const { v4: uuidv4 } = require('uuid');
const logger = require('./logger');
const { AsyncLocalStorage } = require('async_hooks');

const correlationStorage = new AsyncLocalStorage();

function correlationIdMiddleware(req, res, next) {
  // Extract or generate correlation ID
  const correlationId = req.headers['x-correlation-id'] || uuidv4();

  // Store in AsyncLocalStorage
  correlationStorage.run(correlationId, () => {
    // Add to response headers
    res.setHeader('X-Correlation-ID', correlationId);

    // Log with correlation ID
    logger.info('Request received', {
      correlationId,
      method: req.method,
      path: req.path
    });

    // Override logger to automatically include correlation ID
    req.logger = {
      info: (message, meta = {}) => logger.info(message, { ...meta, correlationId }),
      warn: (message, meta = {}) => logger.warn(message, { ...meta, correlationId }),
      error: (message, meta = {}) => logger.error(message, { ...meta, correlationId })
    };

    next();
  });
}

// Get correlation ID from anywhere in request chain
function getCorrelationId() {
  return correlationStorage.getStore();
}

module.exports = { correlationIdMiddleware, getCorrelationId };
```

