#### Step 3: Configure HTTP Client to Propagate Correlation ID

**.NET HttpClient**:
```csharp
// HttpClientCorrelationHandler.cs
public class HttpClientCorrelationHandler : DelegatingHandler
{
    private const string CorrelationIdHeader = "X-Correlation-ID";

    protected override async Task<HttpResponseMessage> SendAsync(
        HttpRequestMessage request,
        CancellationToken cancellationToken)
    {
        // Get correlation ID from context
        var correlationId = CorrelationContext.CorrelationId;

        if (!string.IsNullOrEmpty(correlationId))
        {
            // Add correlation ID to outgoing request
            request.Headers.Add(CorrelationIdHeader, correlationId);
        }

        return await base.SendAsync(request, cancellationToken);
    }
}

// Program.cs registration
builder.Services.AddHttpClient("EligibilityService", client =>
{
    client.BaseAddress = new Uri("http://eligibility-service");
})
.AddHttpMessageHandler<HttpClientCorrelationHandler>();

// Inject and use
public class ClaimsService
{
    private readonly IHttpClientFactory _httpClientFactory;

    public ClaimsService(IHttpClientFactory httpClientFactory)
    {
        _httpClientFactory = httpClientFactory;
    }

    public async Task<EligibilityResult> CheckEligibilityAsync(string memberId)
    {
        var client = _httpClientFactory.CreateClient("EligibilityService");
        // Correlation ID automatically added by handler
        var response = await client.GetAsync($"/api/eligibility/{memberId}");
        return await response.Content.ReadFromJsonAsync<EligibilityResult>();
    }
}
```

**Java Spring Boot RestTemplate**:
```java
@Configuration
public class RestTemplateConfig {

    @Bean
    public RestTemplate restTemplate() {
        RestTemplate restTemplate = new RestTemplate();
        restTemplate.setInterceptors(Collections.singletonList(new CorrelationIdInterceptor()));
        return restTemplate;
    }
}

public class CorrelationIdInterceptor implements ClientHttpRequestInterceptor {

    private static final String CORRELATION_ID_HEADER = "X-Correlation-ID";

    @Override
    public ClientHttpResponse intercept(
            HttpRequest request,
            byte[] body,
            ClientHttpRequestExecution execution) throws IOException {

        // Get correlation ID from MDC
        String correlationId = MDC.get("correlationId");

        if (correlationId != null) {
            request.getHeaders().add(CORRELATION_ID_HEADER, correlationId);
        }

        return execution.execute(request, body);
    }
}
```

