#### Step 4: Propagate Correlation ID in Azure Service Bus Messages

**.NET Azure Service Bus**:
```csharp
// Publishing message with correlation ID
public class ClaimPublisher
{
    private readonly ServiceBusClient _serviceBusClient;
    private readonly ILogger<ClaimPublisher> _logger;

    public ClaimPublisher(ServiceBusClient serviceBusClient, ILogger<ClaimPublisher> logger)
    {
        _serviceBusClient = serviceBusClient;
        _logger = logger;
    }

    public async Task PublishClaimAsync(Claim claim)
    {
        var sender = _serviceBusClient.CreateSender("claims-queue");

        var message = new ServiceBusMessage(JsonSerializer.Serialize(claim))
        {
            MessageId = Guid.NewGuid().ToString(),
            ContentType = "application/json"
        };

        // Add correlation ID to message properties
        var correlationId = CorrelationContext.CorrelationId;
        if (!string.IsNullOrEmpty(correlationId))
        {
            message.ApplicationProperties["correlationId"] = correlationId;
        }

        message.ApplicationProperties["claimId"] = claim.ClaimId;

        _logger.LogInformation("Publishing claim to queue {ClaimId}", claim.ClaimId);

        await sender.SendMessageAsync(message);
    }
}

// Consuming message and extracting correlation ID
public class ClaimProcessor
{
    private readonly ServiceBusProcessor _processor;
    private readonly ILogger<ClaimProcessor> _logger;

    public async Task StartProcessingAsync()
    {
        _processor.ProcessMessageAsync += ProcessMessageAsync;
        _processor.ProcessErrorAsync += ProcessErrorAsync;
        await _processor.StartProcessingAsync();
    }

    private async Task ProcessMessageAsync(ProcessMessageEventArgs args)
    {
        // Extract correlation ID from message properties
        string correlationId = args.Message.ApplicationProperties.ContainsKey("correlationId")
            ? args.Message.ApplicationProperties["correlationId"].ToString()
            : Guid.NewGuid().ToString();

        // Set correlation context for this message processing
        CorrelationContext.CorrelationId = correlationId;

        using (LogContext.PushProperty("CorrelationId", correlationId))
        {
            _logger.LogInformation("Processing claim message {MessageId}", args.Message.MessageId);

            var claim = JsonSerializer.Deserialize<Claim>(args.Message.Body.ToString());

            // Process claim...

            _logger.LogInformation("Claim processed successfully {ClaimId}", claim.ClaimId);

            await args.CompleteMessageAsync(args.Message);
        }
    }
}
```

