[Fact]
public async Task Should_Propagate_Correlation_ID_Through_Services()
{
    // Arrange
    var correlationId = Guid.NewGuid().ToString();
    var client = _factory.CreateClient();
    client.DefaultRequestHeaders.Add("X-Correlation-ID", correlationId);

    // Act
    var response = await client.PostAsync("/api/claims", new StringContent("..."));

    // Assert
    Assert.True(response.Headers.Contains("X-Correlation-ID"));
    Assert.Equal(correlationId, response.Headers.GetValues("X-Correlation-ID").First());

    // Verify correlation ID appears in all service logs
    var logs = _logCollector.GetLogs();
    Assert.All(logs, log => Assert.Equal(correlationId, log.CorrelationId));
}
